import {delta,distance} from '../../games/shared/precision/common.js';
const dt=1/120;
export function paddle(m){const b=m.ball;let target=b.x;if(b.vy>0){const t=Math.max(0,(407-b.y)/b.vy);target=b.x+b.vx*t;const width=330;target=15+Math.abs(((target-15+width)%(2*width)+2*width)%(2*width)-width);const aim=Math.sin(m.time*.63)*.65;target-=aim*m.width/2;}return {targetX:m.x+Math.max(-330*dt,Math.min(330*dt,target-m.x)),action:m.waiting};}
export function cannon(m){let best=m.x,cost=Infinity;for(let x=18;x<=342;x+=9){let danger=0;for(const b of m.bombs){const t=(412-b.y)/135;if(t>=0&&t<1.2&&Math.abs(x-b.x)<20)danger+=100/(t+.1);}const alive=m.aliens.filter(a=>a.alive);const err=Math.min(...alive.map(a=>{const p=m.position(a),flight=(407-p.y)/420,pred=p.x+m.formation.dir*6/m.interval*flight;return Math.abs(x-pred);}));const v=danger+err*.25+Math.abs(x-m.x)*.06;if(v<cost){cost=v;best=x;}}return {left:m.x>best+2,right:m.x<best-2,action:true};}
export function ship(m){const s=m.ship,r=m.rocks.reduce((a,b)=>!a||distance(s,b)-b.r<distance(s,a)-a.r?b:a,null);if(!r)return {action:true};const d=distance(s,r),flight=d/380,angle=Math.atan2(delta(r.y+r.vy*flight,s.y,450),delta(r.x+r.vx*flight,s.x,360)),a=Math.atan2(Math.sin(angle-s.angle),Math.cos(angle-s.angle));return {left:a<-.05,right:a>.05,action:Math.abs(a)<.3,up:(d<r.r+45&&Math.abs(a)<.7)||Math.hypot(s.vx,s.vy)<20,down:d<r.r+15&&m.hyperCooldown===0};}
